calls.content:
{
  "summary": "Enhance the existing URL shortener with persistent redirect analytics, prevent links targeting the shortener itself, and reject destination URLs longer than 2048 characters while preserving all existing endpoint behavior.",
  "changeType": "brownfield",
  "functional": [
    "On each successful short-link redirect, persist a click event containing the link/code, the redirect timestamp, and the HTTP Referer header value when present. A missing Referer must be stored as absent/null.",
    "Add GET /api/links/{code}/analytics. For an existing link, return total click count, daily click counts for the last 30 UTC calendar days, and the five most frequently occurring non-empty referrers with their counts.",
    "The analytics queries must perform counting, date-bounded grouping, ordering, and top-five limiting in the database rather than loading all click events into application memory.",
    "The analytics endpoint must identify the requested link by its short code and return the existing link-not-found response semantics when the code does not exist.",
    "Reject creation of a short link when the destination URL points to the configured public origin of the shortener, including any path, query, or fragment under that origin. Use the existing invalid-URL error response.",
    "Determine the shortener public origin from app.public-origin. If that property is not configured, derive it from server-side application configuration only; never derive it from the incoming request Host header.",
    "Reject creation of any destination URL whose character length exceeds 2048 with the existing invalid-URL error response.",
    "All existing endpoints, successful response bodies, error response bodies, status codes, and redirect behavior must remain unchanged except for the newly required validation and analytics side effects."
  ],
  "nonFunctional": [
    "Redirect analytics persistence must be reliable and associated with the redirecting link; an event must not be recorded for a nonexistent short code.",
    "Analytics retrieval must scale with database aggregation rather than application-memory processing of the complete event history.",
    "Public-origin validation must be resistant to Host-header manipulation and must use normalized URL origin comparison, including scheme, hostname, and effective port.",
    "The analytics response must be deterministic: daily results are ordered chronologically from oldest to newest, and referrers are ordered by descending click count with a deterministic secondary ordering.",
    "The implementation must preserve compatibility with the repository's existing persistence and API conventions."
  ],
  "outOfScope": [
    "Authentication, authorization, rate limiting, bot filtering, or abuse detection for analytics.",
    "Changing the existing short-code format, link creation response, redirect status code, or destination URL validation rules other than the 2048-character and self-origin checks.",
    "Analytics retention, deletion, export, pagination, arbitrary date-range queries, or per-user segmentation.",
    "Capturing request metadata other than the redirect timestamp and Referer header.",
    "Changing the public API documentation beyond documenting the new analytics endpoint and validation behavior."
  ],
  "openQuestions": [
    {
      "question": "What exact JSON property names and nesting should the new analytics response use?",
      "assumption": "Use {\"totalClicks\": number, \"clicksPerDay\": [{\"date\": \"YYYY-MM-DD\", \"clicks\": number}], \"topReferrers\": [{\"referrer\": string, \"clicks\": number}]}.",
      "answer": ""
    },
    {
      "question": "How should the 30-day interval and day boundaries be defined?",
      "assumption": "Use UTC calendar days, including today and the preceding 29 days, and return all 30 dates including dates with zero clicks.",
      "answer": ""
    },
    {
      "question": "Should redirects without a Referer be included in the top-referrers ranking?",
      "assumption": "Include such redirects in totalClicks and clicksPerDay, but exclude null or empty Referer values from topReferrers because they are not referrers.",
      "answer": ""
    },
    {
      "question": "What server configuration should be used when app.public-origin is absent?",
      "assumption": "Build the fallback origin from server-configured scheme, address/hostname, and port, using the application's configured/default server values and not request headers. Normalize a trailing slash before comparison.",
      "answer": ""
    },
    {
      "question": "What constitutes a destination pointing back to the shortener?",
      "assumption": "Treat a destination as self-referential when its normalized scheme, hostname, and effective port match the configured public origin; any path, query, or fragment on that origin is rejected. Origins with different schemes, hostnames, or ports are not rejected by this rule.",
      "answer": ""
    },
    {
      "question": "When should a redirect click event be recorded relative to issuing the redirect response?",
      "assumption": "Record one event after the short code is successfully resolved and immediately before returning the existing redirect response. Missing links do not generate events.",
      "answer": ""
    }
  ],
  "acceptanceCriteria": [
    {
      "id": "AC1",
      "criterion": "Given an existing short code, when a client requests its redirect endpoint with a Referer header, the response remains the existing successful redirect response and a subsequent GET /api/links/{code}/analytics reports the redirect in totalClicks, in the applicable UTC day count, and in the referrer ranking."
    },
    {
      "id": "AC2",
      "criterion": "Given an existing short code, when a client requests its redirect endpoint without a Referer header, the redirect response remains unchanged, totalClicks and the applicable daily count increase by one, and the missing referrer is not emitted as a topReferrers entry."
    },
    {
      "id": "AC3",
      "criterion": "Given an existing link with no click events, GET /api/links/{code}/analytics returns HTTP 200 with totalClicks equal to 0, exactly 30 chronologically ordered daily entries covering today and the previous 29 UTC dates, each with clicks equal to 0, and an empty topReferrers array."
    },
    {
      "id": "AC4",
      "criterion": "Given an existing link with click events across multiple dates, GET /api/links/{code}/analytics returns the correct aggregate total, one clicksPerDay entry per date in the 30-day UTC window including zero-count dates, and excludes events older than that window."
    },
    {
      "id": "AC5",
      "criterion": "Given more than five distinct non-empty referrers, GET /api/links/{code}/analytics returns no more than five topReferrers entries, ordered by descending click count and then deterministic referrer ordering, with counts matching the persisted redirect events."
    },
    {
      "id": "AC6",
      "criterion": "Given an unknown short code, GET /api/links/{code}/analytics returns the existing link-not-found HTTP status and error response shape."
    },
    {
      "id": "AC7",
      "criterion": "When creating a link whose destination has the configured app.public-origin with any path, query, or fragment, the API rejects the request using the existing invalid-URL HTTP status and error response shape, and no link is created."
    },
    {
      "id": "AC8",
      "criterion": "When app.public-origin is unset and a destination matches the origin assembled from server-side configuration, the API rejects it as an invalid URL; changing the request Host header alone must not change whether the destination is classified as self-referential."
    },
    {
      "id": "AC9",
      "criterion": "When creating a link with a destination URL whose length is 2049 characters or greater, the API rejects it using the existing invalid-URL HTTP status and error response shape; a destination of exactly 2048 characters is not rejected solely for length."
    },
    {
      "id": "AC10",
      "criterion": "Existing link creation, lookup, and redirect requests that use valid non-self-referential destinations continue to return their previously defined status codes and response bodies, with redirects still targeting the original destination."
    }
  ],
  "decisions": [
    {
      "title": "Classify the change as brownfield",
      "rationale": "The repository contains implemented controllers, services, persistence classes, integration tests, and URL validation beyond the application template.",
      "alternatives": [
        "greenfield classification based only on the application entry point"
      ]
    },
    {
      "title": "Use a persistent click-event record per redirect",
      "rationale": "The requirement needs timestamp and referrer history and database-side aggregate queries, which requires event-level persistence.",
      "alternatives": [
        "store only pre-aggregated counters",
        "write analytics to an external analytics system"
      ]
    },
    {
      "title": "Use UTC calendar days for daily analytics",
      "rationale": "UTC gives stable, deployment-independent day boundaries and avoids an unspecified client or server timezone.",
      "alternatives": [
        "use the server's local timezone",
        "use the requesting client's timezone"
      ]
    },
    {
      "title": "Return all 30 daily buckets, including zero-count days",
      "rationale": "A fixed 30-day series is easier for API consumers to chart and makes the requested date window explicit.",
      "alternatives": [
        "return only dates having at least one click"
      ]
    },
    {
      "title": "Exclude missing referrers from topReferrers",
      "rationale": "A missing Referer is not a referrer value, while its click must still contribute to total and daily counts.",
      "alternatives": [
        "represent missing referrers as a synthetic value such as direct",
        "include null as a top-referrer entry"
      ]
    },
    {
      "title": "Compare self-referential URLs by normalized origin",
      "rationale": "Any URL served by the shortener, regardless of path or query, can create a redirect loop; origin comparison avoids relying on the request Host header.",
      "alternatives": [
        "reject only an exact configured-origin string",
        "compare full destination URLs including path"
      ]
    },
    {
      "title": "Keep existing invalid-URL error behavior for both new validation failures",
      "rationale": "The requirement explicitly requests the existing invalid-URL error and requires existing API responses to remain compatible.",
      "alternatives": [
        "introduce separate error codes for self-origin and excessive length"
      ]
    },
    {
      "title": "Rank top referrers in the database",
      "rationale": "The requirement explicitly requires database-side ordering and limiting, and this avoids loading all event records into memory.",
      "alternatives": [
        "load events and aggregate in application code",
        "return all referrer groups and limit at the client"
      ]
    }
  ]
}

{
  "tasks": [
    {
      "id": "T1",
      "title": "Add persistent click-event storage and database aggregation queries",
      "description": "Introduce a persistent click-event entity associated with the existing Link record, storing the redirect timestamp and nullable Referer value. Add repository queries for total clicks, UTC date-bounded daily grouping, and non-empty referrer grouping ordered by descending count and deterministic referrer ordering with a database-side limit of five. Follow the repository's existing JPA/schema conventions and ensure events cannot be associated with nonexistent links.",
      "dependsOn": [],
      "files": [
        "src/main/java/com/example/shortener/ClickEvent.java",
        "src/main/java/com/example/shortener/ClickEventRepository.java",
        "src/main/java/com/example/shortener/Link.java",
        "src/main/java/com/example/shortener/LinkRepository.java",
        "src/main/resources/application.yml"
      ],
      "acceptanceCriteria": [
        "AC1",
        "AC2",
        "AC4",
        "AC5"
      ]
    },
    {
      "id": "T2",
      "title": "Implement configured public-origin and destination URL validation",
      "description": "Extend URL validation to reject destinations longer than 2048 characters and destinations whose normalized scheme, hostname, and effective port match the configured shortener public origin. Read app.public-origin when present; otherwise construct the origin exclusively from server-side configuration such as scheme, configured address/hostname, and port, without inspecting the request Host header. Preserve the existing invalid-URL exception, status, and error body.",
      "dependsOn": [],
      "files": [
        "src/main/java/com/example/shortener/UrlValidator.java",
        "src/main/java/com/example/shortener/LinkService.java",
        "src/main/java/com/example/shortener/InvalidUrlException.java",
        "src/main/resources/application.yml"
      ],
      "acceptanceCriteria": [
        "AC7",
        "AC8",
        "AC9",
        "AC10"
      ]
    },
    {
      "id": "T3",
      "title": "Record click events during successful redirects",
      "description": "Update the existing redirect flow so that, after resolving an existing short code and immediately before returning the unchanged redirect response, it persists one click event containing the current timestamp and the nullable Referer header. Do not persist events for unknown codes, and do not alter redirect status, location, or other existing behavior.",
      "dependsOn": [
        "T1"
      ],
      "files": [
        "src/main/java/com/example/shortener/RedirectController.java",
        "src/main/java/com/example/shortener/LinkService.java",
        "src/main/java/com/example/shortener/ClickEventRepository.java"
      ],
      "acceptanceCriteria": [
        "AC1",
        "AC2",
        "AC10"
      ]
    },
    {
      "id": "T4",
      "title": "Add link analytics service and endpoint",
      "description": "Add GET /api/links/{code}/analytics with response fields totalClicks, clicksPerDay, and topReferrers. Resolve the link by short code using existing not-found semantics. Query aggregates through the database repositories, generate the complete 30-date UTC window including zero-count dates in chronological order, and return top referrers excluding null or empty values with deterministic ordering. Avoid loading the complete event history into application memory.",
      "dependsOn": [
        "T1"
      ],
      "files": [
        "src/main/java/com/example/shortener/LinkController.java",
        "src/main/java/com/example/shortener/LinkService.java",
        "src/main/java/com/example/shortener/AnalyticsResponse.java",
        "src/main/java/com/example/shortener/AnalyticsDay.java",
        "src/main/java/com/example/shortener/AnalyticsReferrer.java",
        "src/main/java/com/example/shortener/ClickEventRepository.java",
        "src/main/java/com/example/shortener/GlobalExceptionHandler.java"
      ],
      "acceptanceCriteria": [
        "AC3",
        "AC4",
        "AC5",
        "AC6"
      ]
    },
    {
      "id": "T5",
      "title": "Add regression and integration coverage for analytics and validation",
      "description": "Extend unit and integration tests for click persistence with and without Referer, UTC 30-day aggregation and zero-filled dates, top-five deterministic referrer ordering, unknown-code error behavior, self-origin rejection with paths/queries/fragments, server-configured fallback origin independent of Host headers, 2048-character boundaries, and preservation of existing endpoint responses. Update API documentation for the new endpoint and validation behavior without changing existing endpoint contracts.",
      "dependsOn": [
        "T2",
        "T3",
        "T4"
      ],
      "files": [
        "src/test/java/com/example/shortener/UrlShortenerApplicationTests.java",
        "src/test/java/com/example/shortener/UrlShortenerIntegrationTest.java",
        "src/test/java/com/example/shortener/UrlValidatorTest.java",
        "docs/api.md"
      ],
      "acceptanceCriteria": [
        "AC1",
        "AC2",
        "AC3",
        "AC4",
        "AC5",
        "AC6",
        "AC7",
        "AC8",
        "AC9",
        "AC10"
      ]
    }
  ],
  "risks": [
    {
      "risk": "Database date extraction and UTC grouping may behave differently across the repository's supported database engines or session time zones.",
      "mitigation": "Use explicit UTC timestamp bounds for the 30-day query, document the database-specific date expression if needed, and verify grouping with integration tests against the configured test database."
    },
    {
      "risk": "Adding a click-event relationship to Link may conflict with existing schema generation or cascade behavior.",
      "mitigation": "Follow the existing entity ID and schema conventions, persist events through an explicit repository operation, and verify startup plus redirect persistence in integration tests."
    },
    {
      "risk": "A fallback origin built from wildcard or default server addresses may not be a usable public hostname.",
      "mitigation": "Prefer explicitly configured server address/hostname and port, apply the configured/default scheme, normalize default ports, and never use request-derived Host values; cover configured fallback behavior with tests."
    },
    {
      "risk": "Persisting analytics immediately before the redirect can cause a database failure to affect redirect availability.",
      "mitigation": "Keep the event write minimal and transactional according to existing service conventions, test failure behavior, and preserve the existing redirect response contract wherever the application's persistence policy permits."
    },
    {
      "risk": "Generating zero-count days in application code could be mistaken for in-memory analytics processing.",
      "mitigation": "Only materialize the fixed 30-date calendar scaffold; perform total, date grouping, and referrer ranking in database queries and never load individual click events."
    }
  ],
  "decisions": [
    {
      "title": "Use a dedicated ClickEvent entity associated with Link",
      "rationale": "This preserves referential association with the redirecting link and supports indexed, database-side aggregate queries without changing existing Link API responses.",
      "alternatives": [
        "Store events keyed only by short code",
        "Embed analytics counters directly on Link"
      ]
    },
    {
      "title": "Use the specified analytics response shape",
      "rationale": "The requirements provide an explicit assumption: totalClicks, clicksPerDay entries with date and clicks, and topReferrers entries with referrer and clicks.",
      "alternatives": [
        "Return a map keyed by date",
        "Expose raw database aggregate rows"
      ]
    },
    {
      "title": "Define the analytics window as today plus the preceding 29 UTC calendar days",
      "rationale": "This satisfies the requirement for exactly 30 dates, including today, and makes day boundaries independent of server local time.",
      "alternatives": [
        "Use a rolling 30 times 24-hour interval",
        "Use the server's local calendar timezone"
      ]
    },
    {
      "title": "Exclude null and empty Referer values only from topReferrers",
      "rationale": "Missing referrers must still contribute to total clicks and daily counts while not appearing as referrer rankings.",
      "alternatives": [
        "Exclude missing-referrer events from all analytics",
        "Expose a synthetic '(direct)' referrer"
      ]
    },
    {
      "title": "Compare normalized URL origins using scheme, hostname, and effective port",
      "rationale": "This rejects every path, query, or fragment under the configured origin while correctly distinguishing different schemes, hosts, and ports.",
      "alternatives": [
        "Compare complete destination strings",
        "Compare only hostname"
      ]
    },
    {
      "title": "Use server-side configuration for fallback origin and never the request Host header",
      "rationale": "The requirement explicitly prohibits Host-header-derived classification and requires resistance to Host-header manipulation.",
      "alternatives": [
        "Build the origin from each incoming request",
        "Require app.public-origin with no fallback"
      ]
    },
    {
      "title": "Record the event after successful link resolution and immediately before redirect response creation",
      "rationale": "This ensures nonexistent codes generate no events and matches the specified redirect side-effect timing while preserving the existing response.",
      "alternatives": [
        "Record before link lookup",
        "Record asynchronously after sending the response"
      ]
    }
  ]
}

{
  "impactedFiles": [
    {
      "path": "src/main/java/com/example/shortener/ClickEvent.java",
      "changeKind": "create",
      "reason": "Add a persistent redirect-event entity containing the link association, UTC timestamp, and nullable Referer value."
    },
    {
      "path": "src/main/java/com/example/shortener/ClickEventRepository.java",
      "changeKind": "create",
      "reason": "Provide database-side count, date-bounded daily grouping, and top-referrer aggregation queries with deterministic ordering and a five-row limit."
    },
    {
      "path": "src/main/java/com/example/shortener/AnalyticsResponse.java",
      "changeKind": "create",
      "reason": "Define the analytics response contract with totalClicks, clicksPerDay, and topReferrers."
    },
    {
      "path": "src/main/java/com/example/shortener/AnalyticsService.java",
      "changeKind": "create",
      "reason": "Resolve the link, execute the aggregate repository queries, and fill missing UTC calendar days with zero-count entries without loading click events."
    },
    {
      "path": "src/main/java/com/example/shortener/PublicOriginProvider.java",
      "changeKind": "create",
      "reason": "Resolve and normalize app.public-origin, with a fallback based only on server-side scheme, address, and port configuration."
    },
    {
      "path": "src/main/java/com/example/shortener/UrlValidator.java",
      "changeKind": "modify",
      "reason": "Reject destination strings longer than 2048 characters using InvalidUrlException while retaining existing URL validation behavior."
    },
    {
      "path": "src/main/java/com/example/shortener/LinkService.java",
      "changeKind": "modify",
      "reason": "Reject destinations whose normalized scheme, hostname, and effective port match the configured public origin, and persist a ClickEvent during successful follows."
    },
    {
      "path": "src/main/java/com/example/shortener/RedirectController.java",
      "changeKind": "modify",
      "reason": "Pass the incoming Referer header to the follow operation while preserving the existing 302 redirect response and Location header."
    },
    {
      "path": "src/main/java/com/example/shortener/LinkController.java",
      "changeKind": "modify",
      "reason": "Expose GET /api/links/{code}/analytics and delegate analytics generation while preserving existing link creation and lookup response schemas."
    },
    {
      "path": "src/main/resources/application.yml",
      "changeKind": "modify",
      "reason": "Document/configure the app.public-origin property without making request Host headers part of origin resolution."
    },
    {
      "path": "docs/api.md",
      "changeKind": "modify",
      "reason": "Document the analytics endpoint and the new invalid-destination rules."
    },
    {
      "path": "src/test/java/com/example/shortener/UrlValidatorTest.java",
      "changeKind": "modify",
      "reason": "Add boundary coverage for URLs of exactly 2048 characters and URLs exceeding the limit."
    },
    {
      "path": "src/test/java/com/example/shortener/UrlShortenerIntegrationTest.java",
      "changeKind": "modify",
      "reason": "Verify Referer and missing-Referer redirect analytics, unchanged redirect behavior, self-origin rejection, length rejection, and analytics not-found semantics."
    },
    {
      "path": "src/test/java/com/example/shortener/AnalyticsIntegrationTest.java",
      "changeKind": "create",
      "reason": "Exercise zero-filled 30-day UTC results, date filtering, aggregate totals, null/empty referrer exclusion, deterministic ranking, and the five-referrer limit."
    },
    {
      "path": "src/test/java/com/example/shortener/PublicOriginProviderTest.java",
      "changeKind": "create",
      "reason": "Test normalized origin comparison, effective default ports, configured-origin behavior, server-configuration fallback, and resistance to Host-header manipulation."
    }
  ],
  "impactedApis": [
    {
      "endpoint": "GET /api/links/{code}/analytics",
      "change": "New endpoint returning {\"totalClicks\": number, \"clicksPerDay\": [{\"date\": \"YYYY-MM-DD\", \"clicks\": number}], \"topReferrers\": [{\"referrer\": string, \"clicks\": number}]}; unknown codes use the existing link-not-found response.",
      "backwardCompatible": true
    },
    {
      "endpoint": "GET /{code}",
      "change": "Successful redirects now persist one timestamped click event and optional Referer value; status, Location header, and response body remain unchanged.",
      "backwardCompatible": true
    },
    {
      "endpoint": "POST /api/links",
      "change": "Rejects destinations longer than 2048 characters and destinations under the configured shortener origin with the existing invalid-URL error response.",
      "backwardCompatible": true
    },
    {
      "endpoint": "GET /api/links/{code}",
      "change": "No response contract or click-count behavior change.",
      "backwardCompatible": true
    }
  ],
  "dataChanges": [
    {
      "entity": "ClickEvent",
      "change": "Add a click_events table with an identifier, a non-null association to links, a non-null redirect timestamp, and a nullable Referer column.",
      "migrationImpact": "With the current ddl-auto=update configuration, the table is created automatically in development. A production deployment using managed migrations requires an equivalent additive migration and indexes for link/timestamp and link/referrer aggregation."
    },
    {
      "entity": "Link",
      "change": "Retain the existing click_count column for the existing link response and increment it alongside inserting ClickEvent rows.",
      "migrationImpact": "No destructive schema change; existing links and click counts remain compatible. Historical click_count values cannot be reconstructed into event history."
    }
  ],
  "testsToUpdate": [
    "Extend UrlValidatorTest with the 2048-character acceptance boundary and 2049-character rejection.",
    "Extend UrlShortenerIntegrationTest to send Referer headers, verify missing Referer handling, query analytics, verify unknown analytics codes, reject self-origin URLs under configured and fallback origins, and reject oversized destinations.",
    "Add AnalyticsIntegrationTest covering exactly 30 chronological UTC dates including zeroes, exclusion of older events, total counts, referrer ranking, deterministic tie ordering, null/empty referrers, and a maximum of five results.",
    "Add PublicOriginProviderTest covering configured-origin normalization, effective ports, server-side fallback, and identical classification despite a changed request Host header.",
    "Preserve existing assertions for creation schemas, lookup behavior, redirect status/location, concurrent click counts, and existing error response shapes."
  ],
  "risks": [
    "If click-event insertion and click-count increment are not in the same transaction, analytics totals and the existing clickCount response can diverge.",
    "Database-specific date extraction or timestamp timezone handling could produce incorrect UTC day buckets if queries do not explicitly use UTC-compatible expressions.",
    "Using an unbounded or application-side referrer aggregation would violate the scaling requirement; repository queries must apply grouping, ordering, and limiting in the database.",
    "A fallback based on an unset server address may choose the wrong externally reachable hostname; it must use configured server values and a documented deterministic default, never request headers.",
    "Creating a link with a self-origin destination that differs only by default versus explicit port, case, path, query, or fragment could bypass validation if origin normalization is incomplete.",
    "Persisting the full Referer header without an adequate column size can cause insertion failures for unusually long headers.",
    "The existing click_count value and event count may differ for links created before analytics deployment; analytics should report event data while the legacy link response continues to report click_count.",
    "Database aggregation syntax that works in H2 may not be portable to the production database unless the date-grouping query uses supported JPA/database functions."
  ],
  "decisions": [
    {
      "title": "Keep click_count and add a separate event table",
      "rationale": "Existing link responses depend on click_count, while per-day and referrer analytics require immutable event rows.",
      "alternatives": [
        "Replace click_count with a computed event count, which risks changing existing response behavior and performance.",
        "Store serialized analytics on Link, which cannot support scalable database grouping."
      ]
    },
    {
      "title": "Record events in LinkService.follow before returning the redirect",
      "rationale": "The service already resolves the code and updates click_count, allowing nonexistent codes to produce no events and keeping persistence transactional.",
      "alternatives": [
        "Record events in RedirectController, which duplicates persistence concerns and risks recording unresolved codes.",
        "Use an asynchronous event listener, which weakens the required persistence reliability before the response."
      ]
    },
    {
      "title": "Use database aggregates and application-side zero filling",
      "rationale": "Counting, date-bounded grouping, ordering, and top-five limiting remain database operations, while generating the required 30 entries for dates with no rows is simple and deterministic.",
      "alternatives": [
        "Load all events and aggregate in Java, which violates the scalability requirement.",
        "Require database-generated calendar tables, which adds database-specific schema complexity."
      ]
    },
    {
      "title": "Treat null and empty Referer values as non-referrers",
      "rationale": "They contribute to total and daily counts but are excluded from the top-referrers ranking as required.",
      "alternatives": [
        "Represent missing values as a synthetic referrer label, which would change the specified response semantics."
      ]
    },
    {
      "title": "Use configured public origin only for self-origin validation",
      "rationale": "Existing shortUrl response generation must remain unchanged, while self-loop prevention must not trust the incoming Host header.",
      "alternatives": [
        "Change all generated shortUrl values to the configured origin, which could alter existing endpoint response values.",
        "Use request scheme/host for validation, which is vulnerable to Host-header manipulation."
      ]
    },
    {
      "title": "Use normalized origin comparison with effective ports",
      "rationale": "Self-reference is defined by scheme, hostname, and effective port; paths, queries, and fragments should not affect the comparison.",
      "alternatives": [
        "Compare complete URL strings, which would fail to reject same-origin destinations with different paths or fragments.",
        "Compare only hostnames, which would incorrectly reject different schemes or ports."
      ]
    },
    {
      "title": "Retain the existing invalid-URL exception path",
      "rationale": "Both new creation validations must preserve the established status and ProblemDetail error shape.",
      "alternatives": [
        "Introduce separate validation exceptions, which would require new error handling and risk changing the contract."
      ]
    }
  ]
