    },
    {
      "title": "Use a native H2 date-grouping query with UTC JDBC configuration",
      "rationale": "The service currently uses H2, and native grouping provides database-side daily aggregation while explicit UTC JDBC configuration makes timestamp-to-date conversion deterministic.",
      "alternatives": [
        "Load events and truncate Instants in Java",
        "Use a database-specific JPQL function without explicit timezone configuration",
        "Add a database portability dependency"
      ]
    },
    {
      "title": "Return all 30 daily entries",
      "rationale": "The specified response includes today and the previous 29 UTC dates, including dates with zero clicks. Only the fixed calendar scaffold is generated in Java.",
      "alternatives": [
        "Return only dates present in the aggregate query",
        "Return a date-to-count JSON map"
      ]
    },
    {
      "title": "Limit top referrers in the repository query",
      "rationale": "The requirement requires a database-side top-five limit and deterministic ordering.",
      "alternatives": [
        "Fetch every referrer group and truncate in the service",
        "Store only the five most recent referrers"
      ]
    },
    {
      "title": "Normalize origin by scheme, hostname, and effective port",
      "rationale": "This matches the definition of origin and rejects paths, queries, fragments, case differences, and explicit-versus-implicit default ports under the same origin.",
      "alternatives": [
        "Compare complete URL strings",
        "Compare only hostnames",
        "Compare the configured origin including its path"
      ]
    },
    {
      "title": "Never use the incoming Host header for validation",
      "rationale": "The requirement explicitly requires resistance to Host-header manipulation. The fallback is assembled only from server-side configuration.",
