{"files":[{"path":"src/main/java/com/example/shortener/ClickEvent.java","content":"package com.example.shortener;

import java.time.Instant;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Index;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.ManyToOne;
import jakarta.persistence.Table;

@Entity
@Table(name = "click_events", indexes = {
        @Index(name = "idx_click_events_link_time", columnList = "link_id, occurred_at"),
        @Index(name = "idx_click_events_link_referrer", columnList = "link_id, referrer")
})
public class ClickEvent {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @ManyToOne(fetch = FetchType.LAZY, optional = false)
    @JoinColumn(name = "link_id", nullable = false)
    private Link link;

    @Column(name = "occurred_at", nullable = false)
    private Instant occurredAt;

    @Column(name = "referrer", length = 2048)
    private String referrer;

    protected ClickEvent() {
    }

    public ClickEvent(Link link, Instant occurredAt, String referrer) {
        this.link = link;
        this.occurredAt = occurredAt;
        this.referrer = referrer;
    }
}
"},{"path":"src/main/java/com/example/shortener/ClickEventRepository.java","content":"package com.example.shortener;

import java.time.Instant;
import java.time.LocalDate;
import java.util.List;

import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;

public interface ClickEventRepository extends JpaRepository<ClickEvent, Long> {

    long countByLinkId(Long linkId);

    @Query(value = "select cast(e.occurred_at as date) as day, count(*) as clicks "
            + "from click_events e where e.link_id = :linkId "
            + "and e.occurred_at >= :startInclusive and e.occurred_at < :endExclusive "
            + "group by cast(e.occurred_at as date) order by day", nativeQuery = true)
    List<DailyClicks> findDailyClicks(@Param("linkId") Long linkId,
                                      @Param("startInclusive") Instant startInclusive,
                                      @Param("endExclusive") Instant endExclusive);

    @Query(value = "select e.referrer as referrer, count(*) as clicks "
            + "from click_events e where e.link_id = :linkId "
            + "and e.referrer is not null and e.referrer <> '' "
            + "group by e.referrer order by count(*) desc, e.referrer asc limit 5", nativeQuery = true)
    List<ReferrerClicks> findTopReferrers(@Param("linkId") Long linkId);

    interface DailyClicks {
        LocalDate getDay();
        long getClicks();
    }

    interface ReferrerClicks {
        String getReferrer();
        long getClicks();
    }
}
