"},{"path":"src/main/java/com/example/shortener/PublicOriginProvider.java","content":"package com.example.shortener;

import java.net.URI;
import java.util.Locale;

import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;

@Component
public class PublicOriginProvider {

    private final Origin origin;

    public PublicOriginProvider(
            @Value("${app.public-origin:}") String configuredOrigin,
            @Value("${server.address:localhost}") String serverAddress,
            @Value("${server.port:8080}") int serverPort,
            @Value("${server.ssl.enabled:false}") boolean sslEnabled) {
        String value = configuredOrigin == null || configuredOrigin.isBlank()
                ? (sslEnabled ? "https" : "http") + "://"
                    + (serverAddress == null || serverAddress.isBlank() ? "localhost" : serverAddress)
                    + ":" + serverPort
                : configuredOrigin;
        this.origin = parse(value);
    }

    public boolean matches(URI uri) {
        return origin.matches(uri);
    }

    private static Origin parse(String value) {
        try {
            URI uri = URI.create(value);
            String scheme = uri.getScheme();
            String host = uri.getHost();
            if (scheme == null || host == null
                    || !(scheme.equalsIgnoreCase("http") || scheme.equalsIgnoreCase("https"))) {
                throw new IllegalStateException("app.public-origin must be an HTTP or HTTPS origin");
            }
            return new Origin(scheme.toLowerCase(Locale.ROOT), host.toLowerCase(Locale.ROOT), effectivePort(scheme, uri.getPort()));
        } catch (IllegalArgumentException exception) {
            throw new IllegalStateException("app.public-origin must be a valid HTTP or HTTPS origin", exception);
        }
    }

    private static int effectivePort(String scheme, int port) {
        if (port >= 0) {
            return port;
        }
        return "https".equalsIgnoreCase(scheme) ? 443 : 80;
    }

    private record Origin(String scheme, String host, int port) {
        boolean matches(URI uri) {
            return uri != null && scheme.equalsIgnoreCase(uri.getScheme())
                    && host.equalsIgnoreCase(uri.getHost())
                    && port == effectivePort(uri.getScheme(), uri.getPort());
        }
    }
}
"},{"path":"src/main/java/com/example/shortener/UrlValidator.java","content":"package com.example.shortener;

import java.net.URI;
import java.net.URISyntaxException;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Component;

@Component
public class UrlValidator {

    private final PublicOriginProvider publicOriginProvider;

    public UrlValidator() {
        this.publicOriginProvider = null;
    }

    @Autowired
    public UrlValidator(PublicOriginProvider publicOriginProvider) {
        this.publicOriginProvider = publicOriginProvider;
    }

    public void validate(String value) {
        if (value == null || value.isBlank()) {
            throw new InvalidUrlException("url is required and must not be blank");
        }
        if (value.length() > 2048) {
            throw new InvalidUrlException("url must not exceed 2048 characters");
        }

        try {
            URI uri = new URI(value);
            String scheme = uri.getScheme();
            if (!uri.isAbsolute() || scheme == null
                    || !(scheme.equalsIgnoreCase("http") || scheme.equalsIgnoreCase("https"))
                    || uri.getHost() == null) {
                throw new InvalidUrlException("url must be an absolute HTTP or HTTPS URL");
            }
            if (publicOriginProvider != null && publicOriginProvider.matches(uri)) {
                throw new InvalidUrlException("url must not point to the shortener");
            }
        } catch (URISyntaxException exception) {
            throw new InvalidUrlException("url must be a valid absolute HTTP or HTTPS URL");
        }
    }
}
"},{"path":"src/main/java/com/example/shortener/LinkService.java","content":"package com.example.shortener;

import java.time.Clock;
import java.time.Instant;
import java.util.Optional;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class LinkService {

    private static final int MAX_CREATE_ATTEMPTS = 10;

    private final LinkRepository repository;
    private final ShortCodeGenerator codeGenerator;
    private final ClickEventRepository clickEventRepository;
    private final Clock clock;

    public LinkService(LinkRepository repository, ShortCodeGenerator codeGenerator) {
        this(repository, codeGenerator, null, Clock.systemUTC());
    }

    @Autowired
    public LinkService(LinkRepository repository, ShortCodeGenerator codeGenerator,
                       ClickEventRepository clickEventRepository, Clock clock) {
        this.repository = repository;
        this.codeGenerator = codeGenerator;
        this.clickEventRepository = clickEventRepository;
        this.clock = clock;
    }

    public Link create(String url) {
        for (int attempt = 0; attempt < MAX_CREATE_ATTEMPTS; attempt++) {
            String code = codeGenerator.generate();
            if (repository.existsByCode(code)) {
                continue;
            }
            try {
                return repository.saveAndFlush(new Link(url, code));
            } catch (DataIntegrityViolationException exception) {
                // Retry after a concurrent insert wins the unique-code race.
            }
        }
        throw new CodeGenerationException();
    }

    public Link getByCode(String code) {
        return repository.findByCode(code).orElseThrow(() -> new LinkNotFoundException(code));
    }

    @Transactional
    public String follow(String code, String referer) {
        Optional<Link> link = repository.findByCode(code);
        if (link.isEmpty()) {
            throw new LinkNotFoundException(code);
        }
        if (clickEventRepository != null) {
            String storedReferer = referer == null || referer.isEmpty() ? null : referer;
            clickEventRepository.save(new ClickEvent(link.get(), Instant.now(clock), storedReferer));
        }
        repository.incrementClickCount(code);
        return link.get().getUrl();
    }

    public String follow(String code) {
        return follow(code, null);
    }
}
"},{"path":"src/main/java/com/example/shortener/RedirectController.java","content":"package com.example.shortener;

import java.net.URI;

import org.springframework.http.HttpHeaders;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RestController;

@RestController
public class RedirectController {

    private final LinkService linkService;

    public RedirectController(LinkService linkService) {
        this.linkService = linkService;
    }

    @GetMapping("/{code}")
    public ResponseEntity<Void> redirect(@PathVariable String code,
                                         @RequestHeader(value = "Referer", required = false) String referer) {
        String url = linkService.follow(code, referer);
        HttpHeaders headers = new HttpHeaders();
        headers.setLocation(URI.create(url));
        return new ResponseEntity<>(headers, HttpStatus.FOUND);
    }
}
"},{"path":"src/main/java/com/example/shortener/AnalyticsService.java","content":"package com.example.shortener;

import java.time.Clock;
import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneOffset;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.IntStream;

import org.springframework.stereotype.Service;

@Service
public class AnalyticsService {

    private final LinkRepository linkRepository;
    private final ClickEventRepository clickEventRepository;
    private final Clock clock;

    public AnalyticsService(LinkRepository linkRepository, ClickEventRepository clickEventRepository) {
        this(linkRepository, clickEventRepository, Clock.systemUTC());
    }

    public AnalyticsService(LinkRepository linkRepository, ClickEventRepository clickEventRepository, Clock clock) {
        this.linkRepository = linkRepository;
        this.clickEventRepository = clickEventRepository;
        this.clock = clock;
    }

    public AnalyticsResponse getAnalytics(String code) {
        Link link = linkRepository.findByCode(code).orElseThrow(() -> new LinkNotFoundException(code));
        LocalDate today = LocalDate.now(clock.withZone(ZoneOffset.UTC));
        LocalDate firstDay = today.minusDays(29);
        Instant start = firstDay.atStartOfDay(ZoneOffset.UTC).toInstant();
        Instant end = today.plusDays(1).atStartOfDay(ZoneOffset.UTC).toInstant();

        Map<LocalDate, Long> daily = new HashMap<>();
        for (ClickEventRepository.DailyClicks row : clickEventRepository.findDailyClicks(link.getId(), start, end)) {
            daily.put(row.getDay(), row.getClicks());
        }
        List<AnalyticsDay> days = IntStream.range(0, 30)
                .mapToObj(firstDay::plusDays)
                .map(date -> new AnalyticsDay(date, daily.getOrDefault(date, 0L)))
                .toList();
        List<AnalyticsReferrer> referrers = clickEventRepository.findTopReferrers(link.getId()).stream()
                .map(row -> new AnalyticsReferrer(row.getReferrer(), row.getClicks()))
                .toList();
        return new AnalyticsResponse(clickEventRepository.countByLinkId(link.getId()), days, referrers);
    }
}
"},{"path":"src/main/java/com/example/shortener/LinkController.java","content":"package com.example.shortener;

import java.net.URI;

import jakarta.servlet.http.HttpServletRequest;
import jakarta.validation.Valid;

import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/links")
public class LinkController {

    private final LinkService linkService;
    private final UrlValidator urlValidator;
    private final AnalyticsService analyticsService;

    public LinkController(LinkService linkService, UrlValidator urlValidator, AnalyticsService analyticsService) {
        this.linkService = linkService;
        this.urlValidator = urlValidator;
        this.analyticsService = analyticsService;
    }

    @PostMapping
    public ResponseEntity<LinkResponse> create(@Valid @RequestBody LinkCreateRequest request,
                                               HttpServletRequest httpRequest) {
        urlValidator.validate(request.url());
        Link link = linkService.create(request.url());
        String shortUrl = buildShortUrl(httpRequest, link.getCode());
        return ResponseEntity.created(URI.create(shortUrl)).body(LinkResponse.from(link, shortUrl));
    }

    @GetMapping("/{code}/analytics")
    public AnalyticsResponse analytics(@PathVariable String code) {
        return analyticsService.getAnalytics(code);
    }

    @GetMapping("/{code}")
    public LinkResponse details(@PathVariable String code, HttpServletRequest httpRequest) {
        Link link = linkService.getByCode(code);
        return LinkResponse.from(link, buildShortUrl(httpRequest, link.getCode()));
    }

    private String buildShortUrl(HttpServletRequest request, String code) {
        StringBuilder result = new StringBuilder().append(request.getScheme()).append("://")
                .append(request.getServerName());
        int port = request.getServerPort();
        boolean defaultPort = ("http".equalsIgnoreCase(request.getScheme()) && port == 80)
                || ("https".equalsIgnoreCase(request.getScheme()) && port == 443);
        if (!defaultPort) {
            result.append(':').append(port);
        }
        String contextPath = request.getContextPath();
        if (contextPath != null) {
            result.append(contextPath);
        }
        return result.append('/').append(code).toString();
    }
}
