{"files":[{"path":"src/test/java/com/example/shortener/AnalyticsServiceTest.java","content":"package com.example.shortener;

import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.verifyNoInteractions;
import static org.mockito.Mockito.when;

import java.time.Clock;
import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneOffset;
import java.util.List;
import java.util.Optional;

import org.junit.jupiter.api.Test;

import static org.mockito.Mockito.mock;

class AnalyticsServiceTest {

    @Test
    void buildsThirtyChronologicalDaysAndMapsDatabaseAggregates() {
        LinkRepository links = mock(LinkRepository.class);
        ClickEventRepository events = mock(ClickEventRepository.class);
        Link link = mock(Link.class);
        Clock clock = Clock.fixed(Instant.parse("2026-09-29T12:00:00Z"), ZoneOffset.UTC);

        when(link.getId()).thenReturn(42L);
        when(links.findByCode("abc1234")).thenReturn(Optional.of(link));
        when(events.countByLinkId(42L)).thenReturn(7L);

        ClickEventRepository.DailyClicks today = mock(ClickEventRepository.DailyClicks.class);
        when(today.getDay()).thenReturn(LocalDate.of(2026, 9, 29));
        when(today.getClicks()).thenReturn(3L);
        ClickEventRepository.DailyClicks older = mock(ClickEventRepository.DailyClicks.class);
        when(older.getDay()).thenReturn(LocalDate.of(2026, 9, 1));
        when(older.getClicks()).thenReturn(4L);
        when(events.findDailyClicks(42L,
                Instant.parse("2026-08-31T00:00:00Z"),
                Instant.parse("2026-09-30T00:00:00Z")))
                .thenReturn(List.of(older, today));

        ClickEventRepository.ReferrerClicks referrer = mock(ClickEventRepository.ReferrerClicks.class);
        when(referrer.getReferrer()).thenReturn("https://search.example/");
        when(referrer.getClicks()).thenReturn(5L);
        when(events.findTopReferrers(42L)).thenReturn(List.of(referrer));

        AnalyticsResponse response = new AnalyticsService(links, events, clock).getAnalytics("abc1234");

        assertThat(response.totalClicks()).isEqualTo(7);
        assertThat(response.clicksPerDay()).hasSize(30);
        assertThat(response.clicksPerDay().get(0).date()).isEqualTo(LocalDate.of(2026, 8, 31));
        assertThat(response.clicksPerDay().get(0).clicks()).isEqualTo(0);
        assertThat(response.clicksPerDay().get(1).date()).isEqualTo(LocalDate.of(2026, 9, 1));
        assertThat(response.clicksPerDay().get(1).clicks()).isEqualTo(4);
        assertThat(response.clicksPerDay().get(29).date()).isEqualTo(LocalDate.of(2026, 9, 29));
        assertThat(response.clicksPerDay().get(29).clicks()).isEqualTo(3);
        assertThat(response.topReferrers())
                .containsExactly(new AnalyticsReferrer("https://search.example/", 5));

        verify(events).countByLinkId(42L);
        verify(events).findDailyClicks(42L,
                Instant.parse("2026-08-31T00:00:00Z"),
                Instant.parse("2026-09-30T00:00:00Z"));
        verify(events).findTopReferrers(42L);
    }

    @Test
    void unknownCodeUsesExistingNotFoundExceptionAndDoesNotQueryEvents() {
        LinkRepository links = mock(LinkRepository.class);
        ClickEventRepository events = mock(ClickEventRepository.class);
        when(links.findByCode("missing")).thenReturn(Optional.empty());

        org.assertj.core.api.Assertions.assertThatThrownBy(
                () -> new AnalyticsService(links, events).getAnalytics("missing"))
                .isInstanceOf(LinkNotFoundException.class)
                .hasMessage("No link exists for code: missing");

        verifyNoInteractions(events);
    }
}
"},{"path":"src/test/java/com/example/shortener/UrlValidatorOriginAndLengthTest.java","content":"package com.example.shortener;

import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.util.stream.Stream;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.Arguments;
import org.junit.jupiter.params.provider.MethodSource;

class UrlValidatorOriginAndLengthTest {

    private final PublicOriginProvider origin = new PublicOriginProvider(
            "https://short.example:443", "localhost", 8080, false);
    private final UrlValidator validator = new UrlValidator(origin);

    @ParameterizedTest
    @MethodSource("selfReferentialUrls")
    void rejectsConfiguredOriginRegardlessOfPathQueryFragmentOrDefaultPort(String value) {
        assertThatThrownBy(() -> validator.validate(value))
                .isInstanceOf(InvalidUrlException.class)
                .hasMessage("url must not point to the shortener");
    }

    private static Stream<Arguments> selfReferentialUrls() {
        return Stream.of(
                Arguments.of("https://short.example"),
                Arguments.of("https://SHORT.EXAMPLE:443/anything?x=1#fragment"),
                Arguments.of("https://short.example:443/another-path"));
    }

    @Test
    void rejectsUrlLongerThan2048Characters() {
        String value = "https://external.example/" + "a".repeat(2048);

        assertThatThrownBy(() -> validator.validate(value))
                .isInstanceOf(InvalidUrlException.class)
                .hasMessage("url must not exceed 2048 characters");
    }

    @Test
    void acceptsExactly2048CharactersWhenOtherRulesAreSatisfied() {
        String prefix = "https://external.example/";
        String value = prefix + "a".repeat(2048 - prefix.length());

        org.assertj.core.api.Assertions.assertThat(value).hasSize(2048);
        validator.validate(value);
    }

    @Test
    void fallbackOriginDoesNotDependOnAnIncomingHostHeader() {
        PublicOriginProvider fallback = new PublicOriginProvider("", "localhost", 8080, false);
        UrlValidator fallbackValidator = new UrlValidator(fallback);

        assertThatThrownBy(() -> fallbackValidator.validate("http://localhost:8080/path"))
                .isInstanceOf(InvalidUrlException.class)
                .hasMessage("url must not point to the shortener");
        fallbackValidator.validate("http://attacker.example:8080/path");
    }
}
"},{"path":"src/test/java/com/example/shortener/AnalyticsAndValidationIntegrationTest.java","content":"package com.example.shortener;

import static org.assertj.core.api.Assertions.assertThat;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.header;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneOffset;
import java.util.List;

import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.MvcResult;

import com.jayway.jsonpath.JsonPath;

@SpringBootTest
@AutoConfigureMockMvc
class AnalyticsAndValidationIntegrationTest {

    @Autowired
    private MockMvc mockMvc;

    @Autowired
    private LinkRepository linkRepository;

    @Autowired
    private ClickEventRepository clickEventRepository;

    @Test
    void redirectWithRefererAppearsInAnalyticsAndMissingRefererIsExcludedFromRanking() throws Exception {
        String destination = "https://analytics.example/with-referrer";
        String code = create(destination);

        mockMvc.perform(get("/{code}", code)
                        .header("Referer", "https://search.example/"))
                .andExpect(status().isFound())
                .andExpect(header().string("Location", destination));
        mockMvc.perform(get("/{code}", code))
                .andExpect(status().isFound())
                .andExpect(header().string("Location", destination));

        mockMvc.perform(get("/api/links/{code}/analytics", code))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.totalClicks").value(2))
                .andExpect(jsonPath("$.clicksPerDay", org.hamcrest.Matchers.hasSize(30)))
                .andExpect(jsonPath("$.topReferrers", org.hamcrest.Matchers.hasSize(1)))
                .andExpect(jsonPath("$.topReferrers[0].referrer").value("https://search.example/"))
                .andExpect(jsonPath("$.topReferrers[0].clicks").value(1));
    }

    @Test
    void existingLinkWithNoEventsReturnsThirtyZeroDaysInChronologicalOrder() throws Exception {
        String code = create("https://analytics.example/no-events");
        LocalDate today = LocalDate.now(java.time.Clock.systemUTC());

        MvcResult result = mockMvc.perform(get("/api/links/{code}/analytics", code))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.totalClicks").value(0))
                .andExpect(jsonPath("$.clicksPerDay", org.hamcrest.Matchers.hasSize(30)))
                .andExpect(jsonPath("$.topReferrers", org.hamcrest.Matchers.empty()))
                .andReturn();

        List<?> days = JsonPath.read(result.getResponse().getContentAsString(), "$.clicksPerDay");
        assertThat(days).hasSize(30);
        assertThat(JsonPath.read(result.getResponse().getContentAsString(), "$.clicksPerDay[0].date"))
                .isEqualTo(today.minusDays(29).toString());
        assertThat(JsonPath.read(result.getResponse().getContentAsString(), "$.clicksPerDay[29].date"))
                .isEqualTo(today.toString());
        assertThat(JsonPath.read(result.getResponse().getContentAsString(), "$.clicksPerDay[0].clicks"))
                .isEqualTo(0);
    }

    @Test
    void analyticsUsesDateWindowAndDatabaseTopFiveOrdering() throws Exception {
        String code = create("https://analytics.example/aggregates");
        Link link = linkRepository.findByCode(code).orElseThrow();
        LocalDate today = LocalDate.now(java.time.Clock.systemUTC());
        Instant current = today.atTime(12, 0).toInstant(ZoneOffset.UTC);

        save(link, current, "alpha");
        save(link, current.plusSeconds(1), "alpha");
        save(link, current.plusSeconds(2), "alpha");
        save(link, current.plusSeconds(3), "beta");
        save(link, current.plusSeconds(4), "beta");
        save(link, current.plusSeconds(5), "gamma");
        save(link, current.plusSeconds(6), "delta");
        save(link, current.plusSeconds(7), "epsilon");
        save(link, current.plusSeconds(8), "zeta");
        save(link, current.plusSeconds(9), null);
        save(link, today.minusDays(30).atStartOfDay().toInstant(ZoneOffset.UTC), "old");

        mockMvc.perform(get("/api/links/{code}/analytics", code))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.totalClicks").value(11))
                .andExpect(jsonPath("$.clicksPerDay[29].clicks").value(10))
                .andExpect(jsonPath("$.topReferrers", org.hamcrest.Matchers.hasSize(5)))
                .andExpect(jsonPath("$.topReferrers[0].referrer").value("alpha"))
                .andExpect(jsonPath("$.topReferrers[0].clicks").value(3))
                .andExpect(jsonPath("$.topReferrers[1].referrer").value("beta"))
                .andExpect(jsonPath("$.topReferrers[1].clicks").value(2))
                .andExpect(jsonPath("$.topReferrers[2].referrer").value("delta"))
                .andExpect(jsonPath("$.topReferrers[3].referrer").value("epsilon"))
                .andExpect(jsonPath("$.topReferrers[4].referrer").value("gamma"));
    }

    @Test
    void unknownAnalyticsCodeHasExistingNotFoundProblemDetail() throws Exception {
        mockMvc.perform(get("/api/links/{code}/analytics", "unknown"))
                .andExpect(status().isNotFound())
                .andExpect(jsonPath("$.detail").isNotEmpty());
    }

    @Test
    void rejectsSelfOriginAndOversizedDestinationsWithoutCreatingLinks() throws Exception {
        mockMvc.perform(post("/api/links")
                        .header("Host", "attacker.example")
                        .contentType("application/json")
                        .content("{\"url\":\"http://localhost:8080/some/path?x=1#fragment\"}"))
                .andExpect(status().isBadRequest())
                .andExpect(jsonPath("$.detail").isNotEmpty());

        String prefix = "https://external.example/";
        String oversized = prefix + "a".repeat(2049 - prefix.length());
        mockMvc.perform(post("/api/links")
                        .contentType("application/json")
                        .content("{\"url\":\"" + oversized + "\"}"))
                .andExpect(status().isBadRequest())
                .andExpect(jsonPath("$.detail").isNotEmpty());

        assertThat(linkRepository.findByCode("never-created")).isEmpty();
    }

    @Test
    void exactly2048CharacterDestinationRemainsAccepted() throws Exception {
        String prefix = "https://length.example/";
        String url = prefix + "a".repeat(2048 - prefix.length());

        mockMvc.perform(post("/api/links")
                        .contentType("application/json")
                        .content("{\"url\":\"" + url + "\"}"))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.url").value(url));
    }

    private String create(String url) throws Exception {
        MvcResult result = mockMvc.perform(post("/api/links")
                        .contentType("application/json")
                        .content("{\"url\":\"" + url + "\"}"))
                .andExpect(status().isCreated())
                .andReturn();
        return JsonPath.read(result.getResponse().getContentAsString(), "$.code");
    }

    private void save(Link link, Instant occurredAt, String referrer) {
        clickEventRepository.saveAndFlush(new ClickEvent(link, occurredAt, referrer));
    }
}
