{"files":[{"path":"src/test/java/com/example/shortener/AnalyticsAndValidationIntegrationTest.java","content":"package com.example.shortener;

import static org.assertj.core.api.Assertions.assertThat;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.header;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneOffset;
import java.util.List;

import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.MvcResult;

import com.jayway.jsonpath.JsonPath;

@SpringBootTest
@AutoConfigureMockMvc
class AnalyticsAndValidationIntegrationTest {

    @Autowired
    private MockMvc mockMvc;

    @Autowired
    private LinkRepository linkRepository;

    @Autowired
    private ClickEventRepository clickEventRepository;

    @Test
    void redirectWithRefererAppearsInAnalyticsAndMissingRefererIsExcludedFromRanking() throws Exception {
        String destination = "https://analytics.example/with-referrer";
        String code = create(destination);

        mockMvc.perform(get("/{code}", code)
                        .header("Referer", "https://search.example/"))
                .andExpect(status().isFound())
                .andExpect(header().string("Location", destination));
        mockMvc.perform(get("/{code}", code))
                .andExpect(status().isFound())
                .andExpect(header().string("Location", destination));

        mockMvc.perform(get("/api/links/{code}/analytics", code))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.totalClicks").value(2))
                .andExpect(jsonPath("$.clicksPerDay", org.hamcrest.Matchers.hasSize(30)))
                .andExpect(jsonPath("$.topReferrers", org.hamcrest.Matchers.hasSize(1)))
                .andExpect(jsonPath("$.topReferrers[0].referrer").value("https://search.example/"))
                .andExpect(jsonPath("$.topReferrers[0].clicks").value(1));
    }

    @Test
    void existingLinkWithNoEventsReturnsThirtyZeroDaysInChronologicalOrder() throws Exception {
        String code = create("https://analytics.example/no-events");
        LocalDate today = LocalDate.now(java.time.Clock.systemUTC());

        MvcResult result = mockMvc.perform(get("/api/links/{code}/analytics", code))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.totalClicks").value(0))
                .andExpect(jsonPath("$.clicksPerDay", org.hamcrest.Matchers.hasSize(30)))
                .andExpect(jsonPath("$.topReferrers", org.hamcrest.Matchers.empty()))
                .andReturn();

        String responseBody = result.getResponse().getContentAsString();
        List<?> days = JsonPath.read(responseBody, "$.clicksPerDay");
        assertThat(days).hasSize(30);
        assertThat((String) JsonPath.read(responseBody, "$.clicksPerDay[0].date"))
                .isEqualTo(today.minusDays(29).toString());
        assertThat((String) JsonPath.read(responseBody, "$.clicksPerDay[29].date"))
                .isEqualTo(today.toString());
        assertThat((Object) JsonPath.read(responseBody, "$.clicksPerDay[0].clicks"))
                .isEqualTo(0);
    }

    @Test
    void analyticsUsesDateWindowAndDatabaseTopFiveOrdering() throws Exception {
        String code = create("https://analytics.example/aggregates");
        Link link = linkRepository.findByCode(code).orElseThrow();
        LocalDate today = LocalDate.now(java.time.Clock.systemUTC());
        Instant current = today.atTime(12, 0).toInstant(ZoneOffset.UTC);

        save(link, current, "alpha");
        save(link, current.plusSeconds(1), "alpha");
        save(link, current.plusSeconds(2), "alpha");
        save(link, current.plusSeconds(3), "beta");
        save(link, current.plusSeconds(4), "beta");
        save(link, current.plusSeconds(5), "gamma");
        save(link, current.plusSeconds(6), "delta");
        save(link, current.plusSeconds(7), "epsilon");
        save(link, current.plusSeconds(8), "zeta");
        save(link, current.plusSeconds(9), null);
        save(link, today.minusDays(30).atStartOfDay().toInstant(ZoneOffset.UTC), "old");

        mockMvc.perform(get("/api/links/{code}/analytics", code))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.totalClicks").value(11))
                .andExpect(jsonPath("$.clicksPerDay[29].clicks").value(10))
                .andExpect(jsonPath("$.topReferrers", org.hamcrest.Matchers.hasSize(5)))
                .andExpect(jsonPath("$.topReferrers[0].referrer").value("alpha"))
                .andExpect(jsonPath("$.topReferrers[0].clicks").value(3))
                .andExpect(jsonPath("$.topReferrers[1].referrer").value("beta"))
                .andExpect(jsonPath("$.topReferrers[1].clicks").value(2))
                .andExpect(jsonPath("$.topReferrers[2].referrer").value("delta"))
                .andExpect(jsonPath("$.topReferrers[3].referrer").value("epsilon"))
                .andExpect(jsonPath("$.topReferrers[4].referrer").value("gamma"));
    }

    @Test
    void unknownAnalyticsCodeHasExistingNotFoundProblemDetail() throws Exception {
        mockMvc.perform(get("/api/links/{code}/analytics", "unknown"))
                .andExpect(status().isNotFound())
                .andExpect(jsonPath("$.detail").isNotEmpty());
    }

    @Test
    void rejectsSelfOriginAndOversizedDestinationsWithoutCreatingLinks() throws Exception {
        mockMvc.perform(post("/api/links")
                        .header("Host", "attacker.example")
                        .contentType("application/json")
                        .content("{\"url\":\"http://localhost:8080/some/path?x=1#fragment\"}"))
                .andExpect(status().isBadRequest())
                .andExpect(jsonPath("$.detail").isNotEmpty());

        String prefix = "https://external.example/";
        String oversized = prefix + "a".repeat(2049 - prefix.length());
        mockMvc.perform(post("/api/links")
                        .contentType("application/json")
                        .content("{\"url\":\"" + oversized + "\"}"))
                .andExpect(status().isBadRequest())
                .andExpect(jsonPath("$.detail").isNotEmpty());

        assertThat(linkRepository.findByCode("never-created")).isEmpty();
    }

    @Test
    void exactly2048CharacterDestinationRemainsAccepted() throws Exception {
        String prefix = "https://length.example/";
        String url = prefix + "a".repeat(2048 - prefix.length());

        mockMvc.perform(post("/api/links")
                        .contentType("application/json")
                        .content("{\"url\":\"" + url + "\"}"))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.url").value(url));
    }

    private String create(String url) throws Exception {
        MvcResult result = mockMvc.perform(post("/api/links")
                        .contentType("application/json")
                        .content("{\"url\":\"" + url + "\"}"))
                .andExpect(status().isCreated())
                .andReturn();
        return JsonPath.read(result.getResponse().getContentAsString(), "$.code");
    }

    private void save(Link link, Instant occurredAt, String referrer) {
        clickEventRepository.saveAndFlush(new ClickEvent(link, occurredAt, referrer));
    }
}
"}],"deletes":[],"summary":"Fixed the ambiguous AssertJ assertions caused by JsonPath's generic return type by adding explicit casts. All existing test behavior and coverage remain unchanged.","testCases":[{"name":"redirectWithRefererAppearsInAnalyticsAndMissingRefererIsExcludedFromRanking","type":"integration","covers":["AC1","AC2"]},{"name":"existingLinkWithNoEventsReturnsThirtyZeroDaysInChronologicalOrder","type":"integration","covers":["AC3"]},{"name":"analyticsUsesDateWindowAndDatabaseTopFiveOrdering","type":"integration","covers":["AC4","AC5"]},{"name":"unknownAnalyticsCodeHasExistingNotFoundProblemDetail","type":"integration","covers":["AC6"]},{"name":"rejectsSelfOriginAndOversizedDestinationsWithoutCreatingLinks","type":"integration","covers":["AC7","AC8","AC9"]},{"name":"exactly2048CharacterDestinationRemainsAccepted","type":"integration","covers":["AC9","AC10"]}],"implementationDefects":[],"decisions":[{"title":"Disambiguate JsonPath assertions with explicit casts","rationale":"JsonPath.read returns a generic value that matches multiple overloaded AssertJ assertThat methods, causing compilation failure. Explicit String and Object casts select a single overload without changing test semantics.","alternatives":["Remove the assertions and rely only on MockMvc jsonPath assertions","Use explicit JsonPath generic type parameters"]}]}

{"files":[{"path":"src/main/java/com/example/shortener/ClickEvent.java","content":"package com.example.shortener;

import java.time.Instant;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Index;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.ManyToOne;
import jakarta.persistence.Table;

@Entity
@Table(name = "click_events", indexes = {
        @Index(name = "idx_click_events_link_time", columnList = "link_id, occurred_at"),
        @Index(name = "idx_click_events_link_referrer", columnList = "link_id, referrer")
})
public class ClickEvent {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @ManyToOne(fetch = FetchType.LAZY, optional = false)
    @JoinColumn(name = "link_id", nullable = false)
    private Link link;

    @Column(name = "occurred_at", nullable = false)
    private Instant occurredAt;

    @Column(name = "referrer", length = 4096)
    private String referrer;

    protected ClickEvent() {
    }

    public ClickEvent(Link link, Instant occurredAt, String referrer) {
        this.link = link;
        this.occurredAt = occurredAt;
        this.referrer = referrer;
    }

    public Long getId() {
        return id;
    }

    public Link getLink() {
        return link;
    }

    public Instant getOccurredAt() {
        return occurredAt;
    }

    public String getReferrer() {
        return referrer;
    }
}
"},{"path":"src/main/java/com/example/shortener/ClickEventRepository.java","content":"package com.example.shortener;

import java.time.Instant;
import java.time.LocalDate;
import java.util.List;

import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;

public interface ClickEventRepository extends JpaRepository<ClickEvent, Long> {

    @Query("select count(e) from ClickEvent e where e.link.id = :linkId")
    long countByLinkId(@Param("linkId") Long linkId);

    @Query(value = "select cast(occurred_at as date) as day, count(*) as clicks "
            + "from click_events where link_id = :linkId "
            + "and occurred_at >= :startInclusive and occurred_at < :endExclusive "
            + "group by cast(occurred_at as date) order by cast(occurred_at as date)", nativeQuery = true)
    List<DailyClickProjection> countByDay(@Param("linkId") Long linkId,
            @Param("startInclusive") Instant startInclusive,
            @Param("endExclusive") Instant endExclusive);

    @Query(value = "select referrer as referrer, count(*) as clicks from click_events "
            + "where link_id = :linkId and referrer is not null and referrer <> '' "
            + "group by referrer order by count(*) desc, referrer asc limit 5", nativeQuery = true)
    List<ReferrerClickProjection> topReferrers(@Param("linkId") Long linkId);

    interface DailyClickProjection {
        LocalDate getDay();

        long getClicks();
    }

    interface ReferrerClickProjection {
        String getReferrer();

        long getClicks();
    }
}
