"},{"path":"src/main/java/com/example/shortener/PublicOriginProvider.java","content":"package com.example.shortener;

import java.net.URI;
import java.net.URISyntaxException;
import java.util.Locale;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;

@Component
public class PublicOriginProvider {

    private final Origin origin;

    @Autowired
    public PublicOriginProvider(
            @Value("${app.public-origin:}") String configuredOrigin,
            @Value("${server.address:localhost}") String serverAddress,
            @Value("${server.port:8080}") int serverPort,
            @Value("${server.ssl.enabled:false}") boolean sslEnabled) {
        String host = serverAddress == null || serverAddress.isBlank() ? "localhost" : serverAddress;
        int port = serverPort > 0 ? serverPort : 8080;
        String fallback = (sslEnabled ? "https" : "http") + "://" + host + ":" + port;
        String selected = configuredOrigin == null || configuredOrigin.isBlank()
                ? fallback : configuredOrigin;
        this.origin = parseOrigin(selected);
    }

    public PublicOriginProvider() {
        this.origin = parseOrigin("http://localhost:8080");
    }

    public boolean matches(URI candidate) {
        if (candidate == null || candidate.getScheme() == null || candidate.getHost() == null) {
            return false;
        }
        try {
            return origin.equals(parseOrigin(candidate));
        } catch (IllegalArgumentException exception) {
            return false;
        }
    }

    private static Origin parseOrigin(String value) {
        try {
            return parseOrigin(new URI(value));
        } catch (URISyntaxException | IllegalArgumentException exception) {
            throw new IllegalArgumentException(
                    "app.public-origin must be a valid HTTP or HTTPS origin", exception);
        }
    }

    private static Origin parseOrigin(URI uri) {
        String scheme = uri.getScheme();
        String host = uri.getHost();
        if (scheme == null || host == null
                || !(scheme.equalsIgnoreCase("http") || scheme.equalsIgnoreCase("https"))) {
            throw new IllegalArgumentException("Public origin must be an HTTP or HTTPS URL with a host");
        }
        int port = uri.getPort();
        if (port < 0) {
            port = scheme.equalsIgnoreCase("https") ? 443 : 80;
        }
        return new Origin(scheme.toLowerCase(Locale.ROOT), host.toLowerCase(Locale.ROOT), port);
    }

    private record Origin(String scheme, String host, int port) {
    }
}
